#!/usr/bin/env bash
#
# One-time bootstrap.
#
# This repository holds the AlbionPresence sources (src/, specs/, tests/, docs/,
# assets/). The React Native Android scaffolding (package.json, android/,
# babel/metro/jest/tsconfig configs) is generated by the official React Native
# CLI so that versions and Gradle files are correct for the pinned React Native
# release instead of being hand-copied. This script generates it and overlays
# our sources on top. Run it once, then commit the result.
#
# Requires network access to npm (the CLI template and dependencies are
# downloaded). Override defaults with environment variables:
#   RN_VERSION    React Native version to generate (default below)
#   PACKAGE_NAME  Android application id; it cannot be changed after you publish
#
# UNVERIFIED: written without network access. The React Native CLI flags used
# below follow its documented `init` options; if one is rejected, run
# `npx @react-native-community/cli@latest init --help` and adjust.
set -euo pipefail

RN_VERSION="${RN_VERSION:-0.88.1}"
PACKAGE_NAME="${PACKAGE_NAME:-io.github.aeoncorexlab.albionpresence}"
APP_NAME="AlbionPresence"

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WORK_DIR="$(mktemp -d)"
trap 'rm -rf "$WORK_DIR"' EXIT

if [ -f "$REPO_ROOT/package.json" ]; then
  echo "package.json already exists: bootstrap has already been run. Nothing to do." >&2
  exit 1
fi

echo "==> Generating React Native $RN_VERSION scaffolding ($PACKAGE_NAME)"
(
  cd "$WORK_DIR"
  npx --yes @react-native-community/cli@latest init "$APP_NAME" \
    --version "$RN_VERSION" \
    --package-name "$PACKAGE_NAME" \
    --title "$APP_NAME" \
    --pm npm \
    --skip-git-init \
    --skip-install
)
GENERATED="$WORK_DIR/$APP_NAME"

echo "==> Overlaying generated files without overwriting repository files"
cp -an "$GENERATED/." "$REPO_ROOT/"

cd "$REPO_ROOT"

echo "==> Android only: removing iOS scaffolding (UsageStatsManager is Android-specific)"
rm -rf ios Gemfile .ruby-version

echo "==> Pointing the app entry at src/app/App.tsx"
rm -f App.tsx
rm -rf __tests__
cat > index.js <<'EOF'
import { AppRegistry } from 'react-native';
import App from './src/app/App';
import { name as appName } from './app.json';

AppRegistry.registerComponent(appName, () => App);
EOF

echo "==> Adding scripts and Turbo Native Module codegen config to package.json"
PACKAGE_NAME="$PACKAGE_NAME" node -e '
const fs = require("fs");
const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
pkg.scripts = pkg.scripts || {};
pkg.scripts.typecheck = "tsc --noEmit";
pkg.codegenConfig = {
  name: "AlbionPresenceSpec",
  type: "modules",
  jsSrcsDir: "specs",
  android: { javaPackageName: process.env.PACKAGE_NAME + ".bridge" },
};
fs.writeFileSync("package.json", JSON.stringify(pkg, null, 2) + "\n");
'

echo "==> Registering the pure-Kotlin modules in the Android Gradle settings"
# The same one-line call is valid in both settings.gradle (Groovy) and settings.gradle.kts.
SETTINGS=""
for candidate in android/settings.gradle.kts android/settings.gradle; do
  if [ -f "$candidate" ]; then SETTINGS="$candidate"; break; fi
done
if [ -z "$SETTINGS" ]; then
  echo "Could not find android/settings.gradle(.kts); add this line yourself:" >&2
  echo '  include(":native:monitoring", ":native:session")' >&2
else
  printf '\ninclude(":native:monitoring", ":native:session")\n' >> "$SETTINGS"
fi

echo "==> Ignoring local secrets and the Discord SDK (it must never be committed)"
cat >> .gitignore <<'EOF'

# AlbionPresence
.env
*.keystore
*.jks
local.properties
/vendor/discord_social_sdk/
EOF

echo "==> Installing dependencies"
npm install
npm install zustand react-native-svg react-native-safe-area-context

echo
echo "Done. Next:"
echo "  npm run typecheck && npm test      # TypeScript + unit tests"
echo "  npm run android                    # build and run on a device or emulator"
echo "Then review 'git status' and commit the generated files."
